//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::float::to_string`; the
//! native twin is `benches/native/Bench/FloatToString.lean`.
//! the text formatted into a stack buffer, then one new string object, as
//! lean_mk_ascii_string_unchecked makes

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::float;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &Vec<f64>, n: u64) -> u64 {
    let xs = &inp[..];
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, {
            let mut b = StackBuf::new();
            let _ = float::to_string(get_f64(xs, x >> 52), &mut b);
            make_ascii_string(b.as_bytes()).byte_size()
        });
    }
    acc
}

fn main() {
    run(
        || f64_operands(0xC12E848000000000, 0x413E848000000000, true),
        kernel,
    )
}
